343	    func renderInput(hosts: [DockHostConfiguration]) -> DockRenderInput {
344	        let hostStates = hosts.map { host in
345	            DockHostStateViewModel(
346	                host: DockHostViewModel(host: host),
347	                status: statesByHostID[host.id]?.status ?? .checking
348	            )
349	        }
350	        let statuses = Dictionary(
351	            uniqueKeysWithValues: hostStates.map { ($0.host.id, $0.status) }
352	        )
353	        return DockRenderInput(
354	            hosts: hosts,
355	            hostStates: hostStates,
356	            hostIdentityResolver: DockHostIdentityResolver(
357	                hosts: hosts,
358	                observations: identityObservations(hosts: hosts),
359	                hostStatuses: statuses
360	            ),
361	            cardsByHostID: Dictionary(
362	                uniqueKeysWithValues: hosts.map { host in
363	                    (host.id, sortedCards(for: host))
364	                }
365	            ),
366	            isPartial: hosts.contains(where: needsProgressContext)
367	        )
368	    }
369	
370	    func rowCount(for host: DockHostConfiguration) -> Int {
371	        statesByHostID[host.id]?.cardsByID.count ?? 0
372	    }
373	
374	    func hostIdentityResolver(hosts: [DockHostConfiguration]) -> DockHostIdentityResolver {
375	        DockHostIdentityResolver(
376	            hosts: hosts,
377	            observations: identityObservations(hosts: hosts),
378	            hostStatuses: Dictionary(
379	                uniqueKeysWithValues: hosts.map { host in
380	                    (host.id, statesByHostID[host.id]?.status ?? .checking)
381	                }
382	            )
383	        )
384	    }
385	
386	    private func sortedCards(for host: DockHostConfiguration) -> [DockThreadCardDTO] {
387	        guard let state = statesByHostID[host.id] else {
388	            return []
389	        }
390	        return Array(state.cardsByID.values)
391	            .sorted { lhs, rhs in
392	                if lhs.displayOrderKey != rhs.displayOrderKey {
393	                    return lhs.displayOrderKey < rhs.displayOrderKey
394	                }
395	                return lhs.projectionStorageKey < rhs.projectionStorageKey
396	            }
397	    }
398	
399	    private func identityObservations(hosts: [DockHostConfiguration]) -> [DockHostIdentityObservation] {
400	        hosts.flatMap { host in
401	            guard let state = statesByHostID[host.id] else {
402	                return [DockHostIdentityObservation]()
403	            }
404	            var observations = [DockHostIdentityObservation(
405	                configuredHostID: host.id,
406	                streamHostID: state.sourceHostID
407	            )]
408	            let cardObservations = state.cardsByID.values.map { card in
409	                DockHostIdentityObservation(configuredHostID: host.id, card: card)
410	            }
411	            observations.append(contentsOf: cardObservations)
412	            return observations
413	        }
414	    }
415	
416	    private func needsProgressContext(_ host: DockHostConfiguration) -> Bool {
417	        let status = statesByHostID[host.id]?.status
418	        if case .checking = status {
419	            return true
420	        }
421	        return status?.isDegraded == true
422	    }
423	
424	    private func hostStatus(
425	        freshness: DockStreamFreshnessDTO?,
426	        rowCount: Int,
427	        complete: Bool,
428	        totalRows: Int?,
429	        window: DockStreamWindowDTO?
430	    ) -> DockHostLoadStatus {
431	        let loadedWindow = hostWindow(rowCount: rowCount, complete: complete, totalRows: totalRows, window: window)
432	        guard let freshness else {
433	            return rowCount == 0 && loadedWindow == nil ? .checking : .loaded(rowCount: rowCount, window: loadedWindow)
434	        }
435	        switch freshness.status {
436	        case .fresh:
437	            if rowCount == 0, loadedWindow == nil {
438	                return .empty
439	            }
440	            return .loaded(rowCount: rowCount, window: loadedWindow)
441	        case .stale:
442	            return .degraded(rowCount: rowCount, message: freshness.lastError ?? "Stale")
443	        case .offline:
444	            let message = freshness.lastError ?? "Offline"
445	            return rowCount > 0 ? .degraded(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
446	        case .error:
447	            let message = freshness.lastError ?? "Error"
448	            return rowCount > 0 ? .degraded(rowCount: rowCount, message: message) : .error(message)
449	        case .unknown:
450	            return rowCount == 0 ? .checking : .loaded(rowCount: rowCount, window: loadedWindow)
451	        }
452	    }
453	
454	    private func hostWindow(
455	        rowCount: Int,
456	        complete: Bool,
457	        totalRows: Int?,
458	        window: DockStreamWindowDTO?
459	    ) -> DockHostWindow? {
460	        guard !complete else {
461	            return nil
462	        }
463	        let visibleRows = rowCount
464	        let knownTotal = max(totalRows ?? window?.rowCount ?? visibleRows, visibleRows)
465	        return DockHostWindow(visibleRows: visibleRows, totalRows: knownTotal)
466	    }
467	}
