397	    static func safeSegment(_ value: String) -> String {
398	        var escaped = ""
399	        for byte in value.utf8 {
400	            switch byte {
401	            case 48...57, 65...90, 97...122:
402	                escaped.unicodeScalars.append(UnicodeScalar(Int(byte))!)
403	            case 45, 46, 95:
404	                escaped.unicodeScalars.append(UnicodeScalar(Int(byte))!)
405	            default:
406	                escaped.append(String(format: "%%%02X", byte))
407	            }
408	        }
409	        return escaped.isEmpty ? "_" : escaped
410	    }
411	}
