3	struct DockSwipeActionRow<Content: View>: View {
4	    let row: DockRowViewModel
5	    let actionID: AutomationID
6	    let onTogglePinned: () -> Void
7	    let canOpen: Bool
8	    let onOpen: () -> Void
9	    @ViewBuilder var content: () -> Content
10	    @State private var offset: CGFloat = 0
11	
12	    private let actionWidth: CGFloat = 86
13	
14	    var body: some View {
15	        ZStack(alignment: .trailing) {
16	            if offset != 0 {
17	                swipeButton
18	            }
19	
20	            content()
21	                .offset(x: offset)
22	        }
23	        .contentShape(Rectangle())
24	        .simultaneousGesture(dragGesture)
25	        .onTapGesture(perform: handleTap)
26	        .accessibilityElement(children: .contain)
27	        .accessibilityLabel(row.title)
28	        .accessibilityValue(row.automationValue)
29	        .accessibilityAddTraits(canOpen ? .isButton : [])
30	        .accessibilityAction {
31	            handleTap()
32	        }
33	        .codexAutomationID(AutomationID.Dock.row(hostID: row.hostID, threadID: row.threadID))
34	        // Parent ForEach owns row identity. Do not add a nested .id here;
35	        // live reorders can otherwise leave stale duplicate accessibility rows.
36	        .onChange(of: row.id) { _, _ in
37	            closeAction(animated: false)
38	        }
39	        .onChange(of: row.isPinned) { _, _ in
40	            closeAction(animated: false)
41	        }
42	        .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
43	    }
44	
45	    private var dragGesture: some Gesture {
46	        DragGesture(minimumDistance: 18, coordinateSpace: .local)
47	            .onChanged(updateOffset)
48	            .onEnded(finishDrag)
49	    }
50	
51	    private var swipeButton: some View {
52	        Button(role: row.isPinned ? .destructive : nil) {
53	            closeAction()
54	            onTogglePinned()
55	        } label: {
56	            Label(row.isPinned ? "Unpin" : "Pin", systemImage: row.isPinned ? "pin.slash" : "pin.fill")
57	                .font(.caption.weight(.semibold))
58	                .labelStyle(.titleAndIcon)
59	                .frame(width: actionWidth)
60	                .frame(maxHeight: .infinity)
61	        }
62	        .buttonStyle(.plain)
63	        .foregroundStyle(.white)
64	        .background(row.isPinned ? Color.red : Color.blue)
65	        .codexAutomationID(actionID)
66	    }
67	
68	    private func updateOffset(_ value: DragGesture.Value) {
69	        guard abs(value.translation.width) > abs(value.translation.height) else {
70	            return
71	        }
72	        offset = min(0, max(-actionWidth, value.translation.width))
73	    }
74	
75	    private func finishDrag(_ value: DragGesture.Value) {
76	        let shouldOpen = value.translation.width < -(actionWidth * 0.35)
77	        withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
78	            offset = shouldOpen ? -actionWidth : 0
79	        }
80	    }
81	
82	    private func handleTap() {
83	        if offset != 0 {
84	            closeAction()
85	        } else if canOpen {
86	            onOpen()
87	        }
88	    }
89	
90	    private func closeAction(animated: Bool = true) {
91	        // A live Dock update should not reset the action surface. Only close
92	        // when the user acts or the row's semantic identity/pin state changes.
93	        guard offset != 0 else {
94	            return
95	        }
96	        if animated {
97	            withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
98	                offset = 0
99	            }
100	        } else {
101	            offset = 0
102	        }
103	    }
104	}
