3	public struct ThreadDetailDataSnapshot: Equatable, Sendable {
4	    public let events: [ThreadEvent]
5	    public let activeTurnID: String?
6	
7	    public init(events: [ThreadEvent], activeTurnID: String?) {
8	        self.events = events
9	        self.activeTurnID = activeTurnID
10	    }
11	}
12	
13	public actor ThreadDetailDataEngine {
14	    private var index = ThreadEventIndex()
15	    private var activeTurnID: String?
16	    private var sourceHostID: String?
17	    private var viewParamsKey: String?
18	    private var epoch: String?
19	    private var lastSeq: Int64?
20	
21	    public init() {}
22	
23	    public func replace(
24	        from snapshot: ThreadDetailSnapshotDTO,
25	        expectedThreadID: String,
26	        expectedSourceHostID: String? = nil
27	    ) throws -> ThreadDetailDataSnapshot {
28	        try validateSnapshot(snapshot, expectedThreadID: expectedThreadID, expectedSourceHostID: expectedSourceHostID)
29	        // Thread Detail display identity is relay-owned. The client keys and
30	        // orders only by the relay projection envelope; raw Codex payloads are
31	        // never normalized into production rows here.
32	        index.replace(with: snapshot.rows)
33	        activeTurnID = snapshot.activeTurnID
34	        sourceHostID = snapshot.sourceHostID
35	        viewParamsKey = snapshot.viewParamsKey
36	        epoch = snapshot.epoch
37	        lastSeq = snapshot.seq
38	        return self.snapshot()
39	    }
40	
41	    public func apply(
42	        update: ThreadDetailUpdateDTO,
43	        expectedThreadID: String
44	    ) throws -> ThreadDetailDataSnapshot {
45	        try validate(threadID: update.threadID, expectedThreadID: expectedThreadID)
46	        if isAlreadyCovered(update) {
47	            return snapshot()
48	        }
49	        try validateUpdate(update)
50	        try validateContinuity(update)
51	
52	        switch update.kind {
53	        case .snapshot:
54	            index.replace(with: update.rows)
55	        case .upsert:
56	            for row in update.rows {
57	                try index.upsert(row)
58	            }
59	        case .delete:
60	            for projectionID in update.projectionIDs {
61	                index.remove(id: projectionID)
62	            }
63	        case .heartbeat:
64	            break
65	        case .resyncRequired:
66	            throw ThreadDetailStoreError.projectionResyncRequired(update.reason ?? "Detail resync required.")
67	        }
68	
69	        activeTurnID = update.activeTurnID
70	        lastSeq = update.seq
71	        return snapshot()
72	    }
73	
74	    public func setActiveTurnID(_ activeTurnID: String?) {
75	        self.activeTurnID = activeTurnID
76	    }
77	
78	    public func currentSnapshot() -> ThreadDetailDataSnapshot {
79	        snapshot()
80	    }
81	
82	    private func snapshot() -> ThreadDetailDataSnapshot {
83	        ThreadDetailDataSnapshot(
84	            events: index.eventsNewestFirst(),
85	            activeTurnID: activeTurnID
86	        )
87	    }
88	
89	    private func validate(threadID: String, expectedThreadID: String) throws {
90	        guard threadID == expectedThreadID else {
91	            throw ThreadDetailStoreError.threadMismatch(
92	                expected: expectedThreadID,
93	                actual: threadID
94	            )
95	        }
96	    }
97	
98	    private func validateSnapshot(
99	        _ snapshot: ThreadDetailSnapshotDTO,
100	        expectedThreadID: String,
101	        expectedSourceHostID: String?
102	    ) throws {
103	        try validate(threadID: snapshot.threadID, expectedThreadID: expectedThreadID)
104	        try validateBaseEnvelope(
105	            schemaVersion: snapshot.schemaVersion,
106	            identityVersion: snapshot.identityVersion,
107	            projectionEngineVersion: snapshot.projectionEngineVersion,
108	            sourceHostID: snapshot.sourceHostID,
109	            expectedSourceHostID: expectedSourceHostID,
110	            view: snapshot.view,
111	            order: snapshot.order,
112	            viewParamsKey: snapshot.viewParamsKey
113	        )
114	        try validateRows(
115	            snapshot.rows,
116	            sourceHostID: snapshot.sourceHostID,
117	            view: snapshot.view,
118	            threadID: snapshot.threadID
119	        )
