122	    private func validateUpdate(_ update: ThreadDetailUpdateDTO) throws {
123	        try validateBaseEnvelope(
124	            schemaVersion: update.schemaVersion,
125	            identityVersion: update.identityVersion,
126	            projectionEngineVersion: update.projectionEngineVersion,
127	            sourceHostID: update.sourceHostID,
128	            expectedSourceHostID: sourceHostID,
129	            view: update.view,
130	            order: update.order,
131	            viewParamsKey: update.viewParamsKey
132	        )
133	        guard update.viewParamsKey == viewParamsKey else {
134	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail update viewParamsKey does not match the active view.")
135	        }
136	        try validateRows(
137	            update.rows,
138	            sourceHostID: update.sourceHostID,
139	            view: update.view,
140	            threadID: update.threadID
