145	    private func validateBaseEnvelope(
146	        schemaVersion: Int,
147	        identityVersion: Int,
148	        projectionEngineVersion: Int,
149	        sourceHostID: String,
150	        expectedSourceHostID: String?,
151	        view: String,
152	        order: String?,
153	        viewParamsKey: String?
154	    ) throws {
155	        guard schemaVersion == ThreadDetailProjectionContract.schemaVersion else {
156	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Unsupported Thread Detail schemaVersion \(schemaVersion).")
157	        }
158	        guard identityVersion == ThreadDetailProjectionContract.identityVersion else {
159	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Unsupported Thread Detail identityVersion \(identityVersion).")
160	        }
161	        guard projectionEngineVersion == ThreadDetailProjectionContract.projectionEngineVersion else {
162	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Unsupported Thread Detail projectionEngineVersion \(projectionEngineVersion).")
163	        }
164	        guard !sourceHostID.isEmpty else {
165	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail projection sourceHostID is empty.")
166	        }
167	        if let expectedSourceHostID, sourceHostID != expectedSourceHostID {
168	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail projection sourceHostID \(sourceHostID) does not match \(expectedSourceHostID).")
169	        }
170	        guard view == ThreadDetailProjectionContract.view else {
171	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail projection view \(view) is not \(ThreadDetailProjectionContract.view).")
172	        }
173	        guard order == ThreadDetailProjectionContract.order else {
174	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail projection order is missing or unsupported.")
175	        }
176	        guard let viewParamsKey, !viewParamsKey.isEmpty else {
177	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail projection viewParamsKey is missing.")
178	        }
179	    }
