181	    private func validateRows(
182	        _ rows: [ThreadDetailEventDTO],
183	        sourceHostID: String,
184	        view: String,
185	        threadID: String
186	    ) throws {
187	        var seenProjectionIDs = Set<String>()
188	        var seenSourceKeys = Set<ThreadDetailProjectionSourceKey>()
189	        for row in rows {
190	            guard row.schemaVersion == ThreadDetailProjectionContract.schemaVersion else {
191	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Unsupported Thread Detail row schemaVersion \(row.schemaVersion).")
192	            }
193	            guard row.identityVersion == ThreadDetailProjectionContract.identityVersion else {
194	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Unsupported Thread Detail row identityVersion \(row.identityVersion).")
195	            }
196	            guard row.projectionEngineVersion == ThreadDetailProjectionContract.projectionEngineVersion else {
197	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Unsupported Thread Detail row projectionEngineVersion \(row.projectionEngineVersion).")
198	            }
199	            guard row.sourceHostID == sourceHostID else {
200	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail row sourceHostID does not match its snapshot.")
201	            }
202	            guard row.view == view else {
203	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail row view does not match its snapshot.")
204	            }
205	            guard row.threadID == threadID else {
206	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail row threadID does not match its snapshot.")
207	            }
208	            guard !row.projectionID.isEmpty else {
209	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail row projectionID is empty.")
210	            }
211	            guard !row.sourceRef.isEmpty else {
212	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail row sourceRef is empty.")
213	            }
214	            guard !row.rowRole.isEmpty else {
215	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail row rowRole is empty.")
216	            }
217	            guard !row.displayOrderKey.isEmpty else {
218	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail row displayOrderKey is missing.")
219	            }
220	            guard seenProjectionIDs.insert(row.projectionID).inserted else {
221	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail snapshot contains duplicate projectionID \(row.projectionID).")
222	            }
223	            let sourceKey = ThreadDetailProjectionSourceKey(row)
224	            guard seenSourceKeys.insert(sourceKey).inserted else {
225	                throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail snapshot contains duplicate projection source identity \(row.sourceRef) \(row.rowRole).")
226	            }
227	        }
228	    }
229	
230	    private func validateProjectionIDs(_ projectionIDs: [String]) throws {
231	        for projectionID in projectionIDs where projectionID.isEmpty {
232	            throw ThreadDetailStoreError.invalidProjectionEnvelope("Thread Detail delete projectionID is empty.")
233	        }
234	    }
235	
236	    private func validateContinuity(_ update: ThreadDetailUpdateDTO) throws {
237	        guard let epoch else {
238	            throw ThreadDetailStoreError.projectionEpochMismatch(expected: "none", actual: update.epoch)
239	        }
240	        guard update.epoch == epoch else {
241	            throw ThreadDetailStoreError.projectionEpochMismatch(expected: epoch, actual: update.epoch)
242	        }
243	        guard let lastSeq else {
244	            throw ThreadDetailStoreError.projectionSequenceGap(expected: update.seq, actual: update.seq)
245	        }
246	        guard update.seq == lastSeq + 1 else {
247	            throw ThreadDetailStoreError.projectionSequenceGap(expected: lastSeq + 1, actual: update.seq)
248	        }
249	    }
250	
251	    private func isAlreadyCovered(_ update: ThreadDetailUpdateDTO) -> Bool {
252	        guard let epoch, let lastSeq else {
253	            return false
254	        }
255	        return update.epoch == epoch && update.seq <= lastSeq
256	    }
257	}
