259	private enum ThreadDetailProjectionContract {
260	    static let schemaVersion = 1
261	    static let identityVersion = 1
262	    static let projectionEngineVersion = 1
263	    static let view = "thread.detail"
264	    static let order = "displayOrderKeyAscending"
265	}
