267	struct ThreadEventIndex: Sendable {
268	    private var rowsByProjectionID: [String: ThreadDetailEventDTO] = [:]
269	    private var projectionIDsBySourceKey: [ThreadDetailProjectionSourceKey: String] = [:]
270	
271	    mutating func replace(with rows: [ThreadDetailEventDTO]) {
272	        rowsByProjectionID = Dictionary(
273	            uniqueKeysWithValues: rows.map { row in
274	                (row.projectionID, row)
275	            }
276	        )
277	        projectionIDsBySourceKey = Dictionary(
278	            uniqueKeysWithValues: rows.map { row in
279	                (ThreadDetailProjectionSourceKey(row), row.projectionID)
280	            }
281	        )
282	    }
283	
284	    mutating func upsert(_ row: ThreadDetailEventDTO) throws {
285	        let sourceKey = ThreadDetailProjectionSourceKey(row)
286	        if let existingProjectionID = projectionIDsBySourceKey[sourceKey],
287	           existingProjectionID != row.projectionID {
288	            throw ThreadDetailStoreError.invalidProjectionEnvelope(
289	                "Thread Detail upsert reused projection source identity \(row.sourceRef) \(row.rowRole) under \(row.projectionID); existing projectionID is \(existingProjectionID)."
290	            )
291	        }
292	        if let existing = rowsByProjectionID[row.projectionID] {
293	            guard existing.hasSameProjectionIdentity(as: row) else {
294	                throw ThreadDetailStoreError.invalidProjectionEnvelope(
295	                    "Thread Detail upsert changed immutable projection identity for \(row.projectionID)."
296	                )
297	            }
298	            guard row.revision >= existing.revision else {
299	                throw ThreadDetailStoreError.invalidProjectionEnvelope(
300	                    "Thread Detail upsert carried stale revision \(row.revision) for \(row.projectionID)."
301	                )
302	            }
303	            guard row.revision > existing.revision || row == existing else {
304	                throw ThreadDetailStoreError.invalidProjectionEnvelope(
305	                    "Thread Detail upsert changed row content without increasing revision for \(row.projectionID)."
306	                )
307	            }
308	        }
309	        rowsByProjectionID[row.projectionID] = row
310	        projectionIDsBySourceKey[sourceKey] = row.projectionID
311	    }
312	
313	    mutating func remove(id: String) {
314	        if let existing = rowsByProjectionID.removeValue(forKey: id) {
315	            projectionIDsBySourceKey.removeValue(forKey: ThreadDetailProjectionSourceKey(existing))
316	        }
317	    }
318	
319	    func eventsNewestFirst() -> [ThreadEvent] {
320	        ThreadEventDisplayOrder.newestFirst(rowsByProjectionID.values.map(ThreadEvent.init(detailEvent:)))
321	    }
322	}
