324	private struct ThreadDetailProjectionSourceKey: Hashable, Sendable {
325	    let sourceHostID: String
326	    let view: String
327	    let threadID: String
328	    let sourceRef: String
329	    let rowRole: String
330	
331	    init(_ row: ThreadDetailEventDTO) {
332	        sourceHostID = row.sourceHostID
333	        view = row.view
334	        threadID = row.threadID
335	        sourceRef = row.sourceRef
336	        rowRole = row.rowRole
337	    }
338	}
339	
340	private extension ThreadDetailEventDTO {
341	    func hasSameProjectionIdentity(as other: ThreadDetailEventDTO) -> Bool {
342	        schemaVersion == other.schemaVersion
343	            && identityVersion == other.identityVersion
344	            && projectionEngineVersion == other.projectionEngineVersion
345	            && sourceHostID == other.sourceHostID
346	            && view == other.view
347	            && threadID == other.threadID
348	            && projectionID == other.projectionID
349	            && sourceRef == other.sourceRef
350	            && rowRole == other.rowRole
351	    }
352	}
