38	function safeSegment(value) {
39	  const bytes = Buffer.from(String(value ?? "missing"), "utf8");
40	  let output = "";
41	  for (const byte of bytes) {
42	    const isAlphaNumeric =
43	      (byte >= 0x30 && byte <= 0x39)
44	      || (byte >= 0x41 && byte <= 0x5a)
45	      || (byte >= 0x61 && byte <= 0x7a);
46	    if (isAlphaNumeric || byte === 0x2d || byte === 0x2e || byte === 0x5f) {
