489	  freshnessForHost(hostID, { archived = null } = {}) {
490	    const scopeWhere = archived === null ? "" : " AND archived = ?";
491	    const scopeArgs = archived === null ? [hostID] : [hostID, boolInt(archived)];
492	    const rows = this.db.prepare(`
493	      SELECT complete, last_attempt_at, last_sync_at, last_error
494	      FROM sync_scopes
495	      WHERE host_id = ?
496	      ${scopeWhere}
497	    `).all(...scopeArgs);
498	    if (rows.length === 0) {
499	      return {
500	        status: "unknown",
501	        lastAttemptAt: null,
502	        lastSyncAt: null,
503	        lastError: null,
504	      };
505	    }
506	    const failed = rows.find((row) => row.complete === 0);
507	    const presenceColumn = archived === true
508	      ? "archived_scope_present"
509	      : (archived === false ? "active_scope_present" : "(active_scope_present = 1 OR archived_scope_present = 1)");
510	    const unprovenCards = this.db.prepare(`
511	      SELECT COUNT(*) AS count
512	      FROM threads
513	      WHERE host_id = ?
514	        AND ${archived === null ? presenceColumn : `${presenceColumn} = 1`}
515	        AND (activity_proof_status != 'proven' OR completeness != 'complete' OR freshness_status != 'fresh')
516	    `).get(hostID).count;
517	    const latestAttempt = rows.map((row) => row.last_attempt_at).filter(Boolean).sort().at(-1) || null;
518	    const latestSync = rows.map((row) => row.last_sync_at).filter(Boolean).sort().at(-1) || null;
519	    return {
520	      status: failed || Number(unprovenCards || 0) > 0 ? "stale" : "fresh",
521	      lastAttemptAt: latestAttempt,
522	      lastSyncAt: latestSync,
523	      lastError: failed?.last_error || (Number(unprovenCards || 0) > 0 ? "card activity proof incomplete" : null),
524	    };
