598	  applyDockReconciliation({ host, cards, scopes = [], complete = true, error = null, previousCards = null }) {
599	    const atMs = nowMs();
600	    const at = new Date(atMs).toISOString();
601	    return this.transaction(() => {
602	      this.upsertHost(host, at);
603	      const previousRows = Array.isArray(previousCards)
604	        ? previousCards
605	        : this.listDockCards({ hostID: host.id }).cards;
606	      const previousByID = new Map(previousRows
607	        .map((row) => [cardProjectionKey(row), row])
608	        .filter(([key]) => key));
609	      const existingRows = this.db.prepare(`
610	        SELECT thread_id, archive_state, freshness_status, updated_at
611	        FROM threads
612	        WHERE host_id = ?
613	      `).all(host.id);
614	      const existingByThreadID = new Map(existingRows.map((row) => [row.thread_id, row]));
615	      const nextByID = new Map();
616	      const rows = [];
617	      const projectionIDs = [];
618	
619	      cards.forEach((card) => {
620	        requireProjectionCard(card, DOCK_VIEW);
621	        const existing = existingByThreadID.get(card.threadID);
622	        if (isFreshLocalArchiveMutation(existing, atMs)) {
623	          return;
624	        }
625	        const cardWithOrder = {
626	          ...card,
627	          archiveState: "active",
628	        };
629	        const key = cardProjectionKey(cardWithOrder);
630	        if (!key) {
631	          return;
632	        }
633	        nextByID.set(key, cardWithOrder);
634	        const previous = previousByID.get(key);
635	        if (sortedJSONString(previous) !== sortedJSONString(cardWithOrder)) {
636	          rows.push(cardWithOrder);
637	        }
638	        this.upsertThreadCard(host.id, cardWithOrder, {
639	          archiveState: "active",
640	          activeScopePresent: true,
641	          at,
642	        });
643	      });
644	
645	      if (complete) {
646	        for (const previous of previousRows) {
647	          const key = cardProjectionKey(previous);
648	          if (key && !nextByID.has(key)) {
649	            projectionIDs.push(key);
650	            this.markThreadInactive(host.id, previous.threadID, at);
651	          }
652	        }
653	      }
654	
655	      for (const scope of scopes) {
656	        this.recordSyncScope(host.id, scope, at);
657	      }
658	      if (scopes.length === 0) {
659	        this.recordSyncScope(host.id, {
660	          name: "active:interactiveDefault",
661	          archived: false,
662	          sourceScope: "interactiveDefault",
663	          complete,
664	          error,
665	        }, at);
666	      }
667	
668	      const seq = this.recordChange({
669	        view: DOCK_VIEW,
670	        hostID: host.id,
671	        changeType: "dock-reconcile",
672	        payload: {
673	          upsertCount: rows.length,
674	          deleteCount: projectionIDs.length,
675	          complete,
676	        },
677	        at,
678	      });
679	      this.pruneChanges();
680	      return { seq, rows, projectionIDs };
681	    });
682	  }
