211	  const visibilityCounts = new Map();
212	  const filterCounts = new Map([
213	    ["messages", 0],
214	    ["all", 0],
215	    ["userMessage", 0],
216	    ["agentMessage", 0],
217	    ["command", 0],
218	    ["output", 0],
219	    ["request", 0],
220	    ["system", 0],
221	    ["unknown", 0],
222	  ]);
223	
224	  const rows = projectionRows.map(projectionRowTruth);
225	  for (const row of rows) {
226	    increment(itemTypeCounts, row.itemType);
227	    increment(rowKindCounts, row.kind);
228	    increment(visibilityCounts, row.visibility);
229	    increment(filterCounts, "all");
230	    increment(filterCounts, row.kind);
231	    if (
