359	function relayFilterMoved(relayTruth, relaySamples, filter) {
360	  if (relayTruth?.summary?.filters?.[filter]?.changed === true) {
361	    return true;
362	  }
363	  const counts = relaySamples
364	    .map((sample) => sample?.turns?.visibleCounts?.[filter])
365	    .filter((value) => value !== undefined);
366	  if (new Set(counts).size > 1) {
367	    return true;
