502	function latestRelaySampleAtOrBefore(relaySamples, cutoffMS) {
503	  if (!Number.isFinite(cutoffMS)) {
504	    return null;
505	  }
506	  let selected = null;
507	  for (const sample of relaySamples) {
508	    const sampleMS = relaySampleTimeMS(sample);
509	    if (!Number.isFinite(sampleMS)) {
