557	      filter,
558	      lastUISampledAt: lastUISample?.sampledAt ?? null,
559	      lastUIMessageListCapturedAt: lastUISample?.messageListCapturedAt ?? null,
560	      newestExpectedID,
561	      actualProjectionIDHead: lastUIProjectionIDs[0] ?? null,
562	      relaySampledAt: relaySample?.sampledAt ?? null,
563	      relayFinishedAt: relaySample?.finishedAt ?? null,
564	      maxLagMS,
565	    });
566	  }
