570	function orderedSubsequence(values, reference) {
571	  const referenceIndex = new Map();
572	  reference.forEach((value, index) => {
573	    if (!referenceIndex.has(value)) {
574	      referenceIndex.set(value, index);
575	    }
576	  });
577	  const filtered = values.filter((value) => referenceIndex.has(value));
578	  for (let index = 1; index < filtered.length; index += 1) {
579	    if (referenceIndex.get(filtered[index]) < referenceIndex.get(filtered[index - 1])) {
580	      return false;
581	    }
582	  }
583	  return true;
584	}
