586	function runEvaluation(
587	  runIndex,
588	  run,
589	  samples,
590	  filter,
591	  relaySample,
592	  failures,
593	  extra = {},
594	) {
595	  const counts = samples
596	    .map((sample) => sample.events)
597	    .filter((count) => Number.isInteger(count));
598	  const projectionIDHeads = samples
599	    .map((sample) => sample.uiVisibleProjectionIDs?.[0] ?? null)
600	    .filter(Boolean);
601	  return {
602	    runIndex,
603	    filter,
604	    selectedAt: run.selectedAt || null,
605	    sampleCount: samples.length,
606	    firstUIEvents: counts[0] ?? null,
607	    lastUIEvents: extra.lastUIEvents ?? counts.at(-1) ?? null,
608	    uniqueUIEvents: [...new Set(counts)],
609	    firstUIProjectionIDHead: projectionIDHeads[0] ?? null,
610	    lastUIProjectionIDHead: extra.lastUIProjectionIDs?.[0] ?? projectionIDHeads.at(-1) ?? null,
611	    uniqueUIProjectionIDHeads: [...new Set(projectionIDHeads)],
612	    relaySampledAt: relaySample?.sampledAt ?? null,
613	    relayFinishedAt: relaySample?.finishedAt ?? null,
614	    relayCutoff: extra.relayCutoff ?? null,
615	    expectedEvents: extra.expectedEvents ?? null,
616	    expectedProjectionIDHead: extra.expectedProjectionIDHead ?? null,
617	    ok: failures.length === 0,
618	    failures,
619	  };
620	}
