181	function readReportDir(reportDir) {
182	  const relayReportPath = path.join(reportDir, "relay-client-path.json");
183	  const uiReportPath = path.join(reportDir, "simulator-ui-sync.json");
184	  const relayReport = readJSON(relayReportPath);
185	  const uiReport = readJSON(uiReportPath);
186	  assertProofReport(relayReport, { sourcePath: relayReportPath });
187	  assertProofReport(uiReport, { sourcePath: uiReportPath });
