218	function maxObservedTransitionLag(uiReport) {
219	  const values = transitionChecks(uiReport)
220	    .map((check) => Number(check?.observedLagMs))
221	    .filter((value) => Number.isFinite(value));
222	  const uiLag = Number(uiReport?.summary?.uiLag?.observedLagMs);
223	  if (Number.isFinite(uiLag)) {
224	    values.push(uiLag);
225	  }
226	  return values.length ? Math.max(...values) : null;
