229	function evaluateReportEntry(entry, { maxUiLagMs }) {
230	  const failures = [];
231	  const scenario = scenarioFor(entry);
232	  const requirements = SCENARIO_REQUIREMENTS[scenario] || {};
233	  const routeCounts = routeCountsFor(entry);
234	  const relaySummary = entry.relayReport?.summary || {};
235	  const uiSummary = entry.uiReport?.summary || {};
236	  const relayProofRunID = entry.relayReport?.proofRunID || null;
237	  const uiProofRunID = entry.uiReport?.proofRunID || entry.uiReport?.relayReport?.proofRunID || null;
238	  const scenarioChecks = Number(uiSummary.scenarioTransitionChecks || 0);
239	  const detailChecks = Number(uiSummary.detailTransitionChecks || 0);
240	  const checkpointSweeps = Number(uiSummary.checkpointSweepCount || 0);
241	  const checkpointSweepRowChecks = Number(uiSummary.checkpointSweepRowChecks || 0);
242	  const dockVisibleOrderChecks = Number(uiSummary.dockVisibleOrderChecks || 0);
243	  const dockSweepOrderChecks = Number(uiSummary.dockSweepOrderChecks || 0);
244	  const detailSweeps = Number(uiSummary.detailSweepCount || 0);
245	  const detailSweepMessageCardChecks = Number(uiSummary.detailSweepMessageCardChecks || 0);
246	  const detailMessageOrderChecks = Number(uiSummary.detailMessageOrderChecks || 0);
247	  const maxLag = maxObservedTransitionLag(entry.uiReport);
248	
249	  if (!scenario) {
250	    failures.push({
251	      code: "matrix_scenario_missing",
252	      message: "Controlled simulator report did not name its scenario.",
253	    });
254	  }
255	  if (relaySummary.ok !== true || relaySummary.clientPathOK !== true) {
256	    failures.push({
257	      code: "matrix_relay_report_failed",
258	      message: "Relay client-path report did not pass.",
259	      relayOK: relaySummary.ok ?? null,
260	      clientPathOK: relaySummary.clientPathOK ?? null,
261	    });
262	  }
263	  if (uiSummary.ok !== true) {
264	    failures.push({
265	      code: "matrix_ui_report_failed",
266	      message: "Simulator displayed-UI report did not pass.",
267	      uiOK: uiSummary.ok ?? null,
268	      failureCount: Number(uiSummary.failures || 0),
269	    });
270	  }
271	  if (!relayProofRunID || !uiProofRunID || relayProofRunID !== uiProofRunID) {
272	    failures.push({
273	      code: "matrix_proof_run_mismatch",
274	      message: "Relay and simulator UI reports do not share the same proof run id, so the matrix cannot trust that the artifacts came from the same run.",
275	      relayProofRunID,
276	      uiProofRunID,
277	    });
278	  }
279	  for (const route of requirements.routes || []) {
280	    if (!routeCounts[route]) {
281	      failures.push({
282	        code: "matrix_required_route_missing",
283	        message: `Scenario ${scenario} did not exercise required route ${route}.`,
284	        scenario,
285	        route,
286	      });
287	    }
288	  }
289	  for (const [route, expectedCount] of Object.entries(requirements.minRouteCounts || {})) {
290	    const actualCount = Number(routeCounts[route] || 0);
291	    if (actualCount < expectedCount) {
292	      failures.push({
293	        code: "matrix_required_route_count_too_low",
294	        message: `Scenario ${scenario} did not exercise required route ${route} enough times.`,
295	        scenario,
296	        route,
297	        expected: expectedCount,
298	        actual: actualCount,
299	      });
300	    }
301	  }
302	  if (scenarioChecks < (requirements.minScenarioTransitionChecks || 0)) {
303	    failures.push({
304	      code: "matrix_scenario_transition_checks_missing",
305	      message: `Scenario ${scenario} did not record enough rendered scenario transition checks.`,
306	      scenario,
307	      expected: requirements.minScenarioTransitionChecks || 0,
308	      actual: scenarioChecks,
309	    });
310	  }
311	  if (detailChecks < (requirements.minDetailTransitionChecks || 0)) {
312	    failures.push({
313	      code: "matrix_detail_transition_checks_missing",
314	      message: `Scenario ${scenario} did not record enough rendered detail transition checks.`,
315	      scenario,
316	      expected: requirements.minDetailTransitionChecks || 0,
317	      actual: detailChecks,
318	    });
319	  }
320	  if (checkpointSweeps < (requirements.minCheckpointSweeps || 0)) {
321	    failures.push({
322	      code: "matrix_checkpoint_sweep_missing",
323	      message: `Scenario ${scenario} did not include the required checkpoint sweep.`,
324	      scenario,
325	      expected: requirements.minCheckpointSweeps || 0,
326	      actual: checkpointSweeps,
327	    });
328	  }
329	  if (checkpointSweepRowChecks < (requirements.minCheckpointSweepRowChecks || 0)) {
330	    failures.push({
331	      code: "matrix_checkpoint_sweep_row_checks_missing",
332	      message: `Scenario ${scenario} did not checkpoint enough rendered Dock rows.`,
333	      scenario,
334	      expected: requirements.minCheckpointSweepRowChecks || 0,
335	      actual: checkpointSweepRowChecks,
336	    });
337	  }
338	  if (dockVisibleOrderChecks < (requirements.minDockVisibleOrderChecks || 0)) {
339	    failures.push({
340	      code: "matrix_dock_visible_order_checks_missing",
341	      message: `Scenario ${scenario} did not prove enough visible Dock row ordering.`,
342	      scenario,
343	      expected: requirements.minDockVisibleOrderChecks || 0,
344	      actual: dockVisibleOrderChecks,
345	    });
346	  }
347	  if (dockSweepOrderChecks < (requirements.minDockSweepOrderChecks || 0)) {
348	    failures.push({
349	      code: "matrix_dock_sweep_order_checks_missing",
350	      message: `Scenario ${scenario} did not prove checkpoint Dock row ordering.`,
351	      scenario,
352	      expected: requirements.minDockSweepOrderChecks || 0,
353	      actual: dockSweepOrderChecks,
354	    });
355	  }
356	  if (detailSweeps < (requirements.minDetailSweeps || 0)) {
357	    failures.push({
358	      code: "matrix_detail_sweep_missing",
359	      message: `Scenario ${scenario} did not include the required opened-thread detail sweep.`,
360	      scenario,
361	      expected: requirements.minDetailSweeps || 0,
362	      actual: detailSweeps,
363	    });
364	  }
365	  if (detailSweepMessageCardChecks < (requirements.minDetailSweepMessageCardChecks || 0)) {
366	    failures.push({
367	      code: "matrix_detail_sweep_message_checks_missing",
368	      message: `Scenario ${scenario} did not sweep enough opened-thread detail rows.`,
369	      scenario,
370	      expected: requirements.minDetailSweepMessageCardChecks || 0,
371	      actual: detailSweepMessageCardChecks,
372	    });
373	  }
374	  if (detailMessageOrderChecks < (requirements.minDetailMessageOrderChecks || 0)) {
375	    failures.push({
376	      code: "matrix_detail_message_order_checks_missing",
377	      message: `Scenario ${scenario} did not prove opened-thread message ordering.`,
378	      scenario,
379	      expected: requirements.minDetailMessageOrderChecks || 0,
380	      actual: detailMessageOrderChecks,
381	    });
382	  }
383	  if (uiSummary.scenarioTransitionFailures || uiSummary.detailTransitionFailures) {
384	    failures.push({
385	      code: "matrix_transition_failures_present",
386	      message: `Scenario ${scenario} reported rendered transition failures.`,
387	      scenario,
388	      scenarioTransitionFailures: uiSummary.scenarioTransitionFailures || 0,
389	      detailTransitionFailures: uiSummary.detailTransitionFailures || 0,
390	    });
391	  }
392	  if (entry.uiReport?.summary?.uiLag?.ok === false || (maxLag !== null && maxLag > maxUiLagMs)) {
393	    failures.push({
394	      code: "matrix_ui_lag_exceeded",
395	      message: `Scenario ${scenario} exceeded the rendered UI lag budget.`,
396	      scenario,
397	      observedMs: maxLag,
398	      budgetMs: maxUiLagMs,
399	    });
400	  }
401	
402	  return {
403	    scenario,
404	    dir: entry.dir || null,
405	    relayReportPath: entry.relayReportPath || null,
406	    uiReportPath: entry.uiReportPath || null,
407	    proofRunID: relayProofRunID,
408	    ok: failures.length === 0,
409	    routeCounts,
410	    uiSampleCount: Number(uiSummary.uiSampleCount || 0),
411	    scoredUISampleCount: Number(uiSummary.scoredUISampleCount || 0),
412	    checkpointSweepCount: checkpointSweeps,
413	    checkpointSweepRowChecks,
414	    dockVisibleOrderChecks,
415	    dockSweepOrderChecks,
416	    detailSweepCount: detailSweeps,
417	    detailSweepMessageCardChecks,
418	    detailMessageOrderChecks,
419	    scenarioTransitionChecks: scenarioChecks,
420	    detailTransitionChecks: detailChecks,
421	    maxObservedUiLagMs: maxLag,
422	    failures,
423	  };
424	}
425	
426	function buildMatrixReport({ entries, requiredScenarios = DEFAULT_REQUIRED_SCENARIOS, minPasses = 1, maxUiLagMs = DEFAULT_MAX_UI_LAG_MS }) {
427	  const evaluated = entries.map((entry) => evaluateReportEntry(entry, { maxUiLagMs }));
428	  const findings = [];
429	  const byScenario = new Map();
430	  for (const result of evaluated) {
431	    if (!result.scenario) {
432	      findings.push(...result.failures.map((failure) => ({ ...failure, dir: result.dir })));
433	      continue;
434	    }
435	    if (!byScenario.has(result.scenario)) {
436	      byScenario.set(result.scenario, []);
437	    }
438	    byScenario.get(result.scenario).push(result);
439	    for (const failure of result.failures) {
440	      findings.push({ ...failure, scenario: result.scenario, dir: result.dir });
441	    }
442	  }
443	
444	  const scenarioSummaries = requiredScenarios.map((scenario) => {
445	    const reports = byScenario.get(scenario) || [];
446	    const passingReports = reports.filter((report) => report.ok);
447	    const reportDirs = passingReports.map((report) => report.dir).filter(Boolean);
448	    const duplicateReportDirs = reportDirs.filter((dir, index) => reportDirs.indexOf(dir) !== index);
449	    const status = passingReports.length >= minPasses ? "pass" : reports.length ? "fail" : "missing";
450	    if (status === "missing") {
451	      findings.push({
452	        code: "matrix_required_scenario_missing",
453	        message: `Required controlled simulator scenario ${scenario} has no report.`,
454	        scenario,
455	      });
456	    } else if (status === "fail") {
457	      findings.push({
458	        code: "matrix_required_scenario_insufficient_passes",
459	        message: `Required controlled simulator scenario ${scenario} has ${passingReports.length} passing report(s), expected ${minPasses}.`,
460	        scenario,
461	        expected: minPasses,
462	        actual: passingReports.length,
463	      });
464	    }
465	    if (duplicateReportDirs.length) {
466	      findings.push({
467	        code: "matrix_duplicate_report_dir",
468	        message: `Required controlled simulator scenario ${scenario} repeats a report directory, so it cannot count as an independent matrix pass.`,
469	        scenario,
470	        dirs: [...new Set(duplicateReportDirs)].sort(),
471	      });
472	    }
473	    const lagValues = reports
474	      .map((report) => report.maxObservedUiLagMs)
475	      .filter((value) => Number.isFinite(value));
476	    return {
477	      scenario,
478	      status: duplicateReportDirs.length ? "fail" : status,
479	      reportCount: reports.length,
480	      passingReportCount: passingReports.length,
481	      maxObservedUiLagMs: lagValues.length ? Math.max(...lagValues) : null,
482	      reports,
483	    };
484	  });
485	
486	  const unexpectedScenarios = [...byScenario.keys()]
487	    .filter((scenario) => !requiredScenarios.includes(scenario))
488	    .sort();
489	  for (const scenario of unexpectedScenarios) {
490	    findings.push({
491	      code: "matrix_unexpected_scenario",
492	      severity: "warning",
493	      message: `Controlled simulator matrix included unexpected scenario ${scenario}.`,
494	      scenario,
495	    });
496	  }
497	
498	  const allLagValues = evaluated
499	    .map((report) => report.maxObservedUiLagMs)
500	    .filter((value) => Number.isFinite(value));
501	  const ok = findings.filter((finding) => finding.severity !== "warning").length === 0;
502	  return {
503	    schemaVersion: 1,
504	    kind: "codex-dock-controlled-simulator-matrix-report",
505	    generatedAt: new Date().toISOString(),
506	    config: {
507	      requiredScenarios,
508	      minPasses,
509	      maxUiLagMs,
510	    },
511	    summary: {
512	      ok,
513	      reportCount: entries.length,
514	      evaluatedReportCount: evaluated.length,
515	      requiredScenarioCount: requiredScenarios.length,
516	      passingScenarioCount: scenarioSummaries.filter((scenario) => scenario.status === "pass").length,
517	      missingScenarioCount: scenarioSummaries.filter((scenario) => scenario.status === "missing").length,
518	      failedScenarioCount: scenarioSummaries.filter((scenario) => scenario.status === "fail").length,
519	      unexpectedScenarioCount: unexpectedScenarios.length,
520	      maxObservedUiLagMs: allLagValues.length ? Math.max(...allLagValues) : null,
521	      findings: findings.length,
522	    },
523	    scenarios: scenarioSummaries,
524	    unexpectedScenarios,
525	    findings,
526	  };
527	}
528	
529	function markdownSummary(report) {
530	  const lines = [];
531	  lines.push("# Codex Dock Controlled Simulator Matrix");
532	  lines.push("");
533	  lines.push(`Generated: \`${report.generatedAt}\``);
534	  lines.push("");
535	  lines.push("## Summary");
536	  lines.push("");
537	  lines.push(`- OK: ${report.summary.ok ? "true" : "false"}`);
538	  lines.push(`- Reports: ${report.summary.reportCount}`);
539	  lines.push(`- Required scenarios: ${report.summary.requiredScenarioCount}`);
540	  lines.push(`- Passing scenarios: ${report.summary.passingScenarioCount}`);
541	  lines.push(`- Missing scenarios: ${report.summary.missingScenarioCount}`);
542	  lines.push(`- Failed scenarios: ${report.summary.failedScenarioCount}`);
543	  lines.push(`- Max observed UI lag: ${report.summary.maxObservedUiLagMs ?? "not scored"} ms`);
544	  lines.push(`- UI lag budget: ${report.config.maxUiLagMs} ms`);
545	  lines.push("");
546	  lines.push("## Scenarios");
547	  lines.push("");
548	  for (const scenario of report.scenarios) {
549	    lines.push(`- \`${scenario.scenario}\`: ${scenario.status}, passes ${scenario.passingReportCount}/${report.config.minPasses}, reports ${scenario.reportCount}, max UI lag ${scenario.maxObservedUiLagMs ?? "not scored"} ms`);
550	  }
551	  lines.push("");
552	  lines.push("## Findings");
553	  lines.push("");
554	  if (!report.findings.length) {
555	    lines.push("- None.");
556	  } else {
557	    for (const finding of report.findings.slice(0, 80)) {
558	      lines.push(`- \`${finding.code}\`: ${finding.message}`);
559	    }
560	    if (report.findings.length > 80) {
561	      lines.push(`- ${report.findings.length - 80} more findings omitted from summary.`);
562	    }
563	  }
564	  lines.push("");
565	  return `${lines.join("\n")}\n`;
566	}
567	
568	function writeReportFiles(report, options) {
569	  finalizeProofReport(report);
570	  assertProofReport(report);
571	  fs.mkdirSync(path.dirname(options.jsonOut), { recursive: true });
572	  fs.writeFileSync(options.jsonOut, `${JSON.stringify(report, null, 2)}\n`, "utf8");
573	  if (options.summaryOut) {
574	    fs.mkdirSync(path.dirname(options.summaryOut), { recursive: true });
575	    fs.writeFileSync(options.summaryOut, markdownSummary(report), "utf8");
576	  }
577	}
578	
579	async function main() {
580	  const options = parseArgs(process.argv.slice(2));
581	  if (options.help) {
582	    console.log(usage());
583	    return;
584	  }
585	  validateOptions(options);
586	  const entries = options.reportDirs.map(readReportDir);
587	  const report = buildMatrixReport({
588	    entries,
589	    requiredScenarios: options.requiredScenarios,
590	    minPasses: options.minPasses,
591	    maxUiLagMs: options.maxUiLagMs,
592	  });
593	  writeReportFiles(report, options);
594	  process.stdout.write(`${JSON.stringify({
595	    ok: report.summary.ok,
596	    summary: report.summary,
597	    reportPath: options.jsonOut,
598	    summaryPath: options.summaryOut || null,
599	    findings: report.findings.slice(0, 20),
600	  }, null, 2)}\n`);
601	  if (options.failOnDiff && !report.summary.ok) {
602	    process.exitCode = 1;
603	  }
604	}
605	
606	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
607	  main().catch((error) => {
608	    console.error(`controlled-simulator-matrix failed: ${error.message || error}`);
609	    process.exit(1);
610	  });
611	}
612	
613	export {
614	  buildMatrixReport,
615	  evaluateReportEntry,
616	  markdownSummary,
617	  parseArgs,
618	  readReportDir,
619	  validateOptions,
620	};
