2	
3	struct ArchiveThreadCardProjector {
4	    let hosts: [DockHostConfiguration]
5	    let hostIdentityResolver: DockHostIdentityResolver
6	    let localMetadata: [LocalThreadMetadataKey: LocalThreadMetadata]
7	    let now: @Sendable () -> Date
8	
9	    func sections(from cardBatches: [(hostID: String, cards: [DockThreadCardDTO])]) -> [DockSectionViewModel] {
10	        let rowProjector = ThreadCardRowProjector(
11	            hosts: hosts,
12	            hostIdentityResolver: hostIdentityResolver,
13	            localMetadata: localMetadata,
14	            now: now
15	        )
16	        let rows = cardBatches.flatMap { batch in
17	            rowProjector.rows(from: batch.cards)
18	        }
19	        let groupedRows = Dictionary(grouping: rows, by: sectionID(for:))
20	
21	        return groupedRows
22	            .map { sectionID, rows in
23	                DockSectionViewModel(
24	                    id: sectionID,
25	                    title: sectionTitle(for: rows[0]),
26	                    rows: rows.sorted(by: rowPrecedes)
27	                )
28	            }
29	            .sorted(by: sectionPrecedes)
30	    }
31	
32	    private func sectionID(for row: DockRowViewModel) -> String {
33	        hosts.count > 1 ? "\(row.hostID)::\(row.branch)" : row.branch
34	    }
35	
36	    private func sectionTitle(for row: DockRowViewModel) -> String {
37	        guard hosts.count > 1 else {
38	            return row.branch
39	        }
40	        return "\(row.hostDisplayName) / \(row.branch)"
41	    }
42	
43	    private func sectionPrecedes(_ lhs: DockSectionViewModel, _ rhs: DockSectionViewModel) -> Bool {
44	        // Archive ordering follows relay displayOrderKey only. Do not rebuild
45	        // recency locally from timestamps.
46	        if let lhsOrderKey = sectionOrderKey(lhs),
47	           let rhsOrderKey = sectionOrderKey(rhs),
48	           lhsOrderKey != rhsOrderKey {
49	            return lhsOrderKey < rhsOrderKey
50	        }
51	
52	        return lhs.title.localizedCaseInsensitiveCompare(rhs.title) == .orderedAscending
53	    }
54	
55	    private func sectionOrderKey(_ section: DockSectionViewModel) -> String? {
56	        section.rows.map(\.displayOrderKey).min()
57	    }
58	
59	    private func rowPrecedes(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
60	        // The relay owns card recency. Archive may group rows, but row order is
61	        // still relay displayOrderKey, then projectionID.
62	        if lhs.displayOrderKey != rhs.displayOrderKey {
63	            return lhs.displayOrderKey < rhs.displayOrderKey
64	        }
65	
66	        return lhs.id < rhs.id
67	    }
68	}
