750	    case DOCK_RESYNC_METHOD:
751	      return relayStateEngineForConfig(config).resyncDock({ downstreamWs, sendJson });
752	    case ARCHIVE_SUBSCRIBE_METHOD:
753	      return relayStateEngineForConfig(config).subscribeArchive({ session, downstreamWs, sendJson });
754	    case ARCHIVE_RESYNC_METHOD:
755	      return relayStateEngineForConfig(config).resyncArchive({ downstreamWs, sendJson });
756	    case "thread/detail/read":
757	      return readThreadDetail(config, params || {});
758	    case "thread/detail/subscribe":
759	      return subscribeThreadDetail(config, params || {}, session, downstreamWs);
760	    case "thread/detail/resync":
761	      return resyncThreadDetail(config, params || {}, session);
762	    case "projection/witness/read":
763	      return readProjectionWitness(config, params || {});
764	    case "thread/archive":
