351	                    hostID: host.id,
352	                    route: "archive/subscribe",
353	                    status: "checking",
354	                    phase: .checking
355	                )
356	            }
357	        case .loaded(let snapshot), .empty(let snapshot), .unavailable(let snapshot, _):
358	            return snapshot.hostStates.map { hostState in
359	                ConnectivityRuntimeEvent(
360	                    source: .archive,
361	                    hostID: hostState.host.id,
362	                    route: "archive/subscribe",
363	                    status: hostState.status.subtitle,
364	                    phase: Self.connectivityPhase(for: hostState.status)
365	                )
366	            }
367	        }
