2	
3	actor ArchiveCleanupDataEngine {
4	    private let now: @Sendable () -> Date
5	
6	    init(now: @escaping @Sendable () -> Date = Date.init) {
7	        self.now = now
8	    }
9	
10	    func makePreview(
11	        from snapshot: DockSnapshot,
12	        rule: ArchiveCleanupRule
13	    ) -> ArchiveCleanupPreviewSnapshot {
14	        let rows = snapshot.rows
15	
16	        var candidates: [DockRowViewModel] = []
17	        var excluded: [ArchiveCleanupExcludedRow] = []
18	        for row in rows {
19	            if let reason = exclusionReason(for: row, rule: rule) {
20	                excluded.append(ArchiveCleanupExcludedRow(row: row, reason: reason))
21	            } else {
22	                candidates.append(row)
23	            }
24	        }
25	
26	        let hostSummaries = snapshot.hosts.map { host in
27	            ArchiveCleanupHostSummary(
28	                id: host.id,
29	                displayName: host.displayName,
30	                candidateCount: candidates.filter { row in
31	                    snapshot.hostIdentityResolver.contains(
32	                        rowHostID: row.hostID,
33	                        sourceConfiguredHostID: row.sourceHostID,
34	                        in: host.id
35	                    )
36	                }.count,
37	                excludedCount: excluded.filter { excludedRow in
38	                    snapshot.hostIdentityResolver.contains(
39	                        rowHostID: excludedRow.row.hostID,
40	                        sourceConfiguredHostID: excludedRow.row.sourceHostID,
41	                        in: host.id
42	                    )
43	                }.count
44	            )
45	        }
46	
47	        return ArchiveCleanupPreviewSnapshot(
48	            hosts: snapshot.hosts,
49	            hostStates: snapshot.hostStates,
50	            hostIdentityResolver: snapshot.hostIdentityResolver,
51	            hostSummaries: hostSummaries,
52	            candidates: candidates.sorted(by: rowPrecedes),
53	            excluded: excluded.sorted { lhs, rhs in
54	                rowPrecedes(lhs.row, rhs.row)
55	            }
56	        )
57	    }
58	
59	    private func rowPrecedes(_ lhs: DockRowViewModel, _ rhs: DockRowViewModel) -> Bool {
60	        // Cleanup previews use relay displayOrderKey, then projectionID.
61	        if lhs.displayOrderKey != rhs.displayOrderKey {
62	            return lhs.displayOrderKey < rhs.displayOrderKey
63	        }
64	        return lhs.id < rhs.id
65	    }
66	
67	    private func exclusionReason(
68	        for row: DockRowViewModel,
69	        rule: ArchiveCleanupRule
70	    ) -> ArchiveCleanupExclusionReason? {
71	        let cutoff = now().addingTimeInterval(-Double(rule.age.days) * 86_400)
72	        if row.lastActivityDate >= cutoff {
73	            return .tooRecent
74	        }
75	        if row.origin.kind != .humanInteractive {
76	            return .nonHuman
77	        }
78	        if rule.excludesPinned, row.isPinned {
79	            return .pinned
80	        }
81	        if rule.excludesRunning, row.status == .running {
82	            return .running
83	        }
84	        if rule.excludesNeedsInput, row.status == .needsInput {
85	            return .needsInput
86	        }
87	        if rule.excludesNeedsInput, row.status == .needsApproval {
88	            return .needsApproval
89	        }
90	        if rule.excludesWatchLabel, row.label?.localizedCaseInsensitiveCompare("Watch") == .orderedSame {
91	            return .watchLabel
92	        }
93	        return nil
94	    }
95	}
