4	@MainActor
5	public final class ArchiveCleanupStore: ObservableObject {
6	    @Published public private(set) var state: ArchiveCleanupStoreState
7	    @Published public private(set) var selectedRowIDs: Set<HostScopedThreadID> = []
8	    @Published public private(set) var executionResults: [ArchiveCleanupExecutionResult] = []
9	    @Published public private(set) var isExecuting = false
10	    @Published public private(set) var stopRemainingRequested = false
11	    @Published public private(set) var executionTotalCount = 0
12	
13	    private var hosts: [DockHostConfiguration]
14	    private var dataEngine: ArchiveCleanupDataEngine?
15	    private let cardStateProvider: (any DockCardStateProviding)?
16	    private let archiver: any ThreadArchiveCommanding
17	
18	    public init(
19	        registry: HostRegistry,
20	        cardStateProvider: any DockCardStateProviding,
21	        archiver: any ThreadArchiveCommanding = AppServerThreadCommandClient(),
22	        now: @escaping @Sendable () -> Date = Date.init
23	    ) {
24	        self.hosts = registry.hosts
25	        self.archiver = archiver
26	        self.cardStateProvider = cardStateProvider
27	        self.dataEngine = ArchiveCleanupDataEngine(now: now)
28	        self.state = .idle(registry.hosts.map(DockHostViewModel.init))
29	    }
30	
31	    public init(configurationError error: Error) {
32	        self.hosts = []
33	        self.archiver = AppServerThreadCommandClient()
34	        self.cardStateProvider = nil
35	        self.dataEngine = nil
36	        self.state = .configurationError(error.localizedDescription)
37	    }
38	
39	    public func updateRegistry(_ registry: HostRegistry) async {
40	        hosts = registry.hosts
41	        state = .idle(registry.hosts.map(DockHostViewModel.init))
42	        selectedRowIDs = []
43	    }
44	
45	    public func loadPreview(rule: ArchiveCleanupRule) async {
46	        guard let dataEngine else {
47	            state = .failed("Archive cleanup is not configured.")
48	            return
49	        }
50	        guard let cardStateProvider else {
51	            state = .failed("Dock stream state is not available.")
52	            selectedRowIDs = []
53	            return
54	        }
55	        state = .loading(hosts.map(DockHostViewModel.init))
56	        await cardStateProvider.refresh()
57	        guard let dockSnapshot = cardStateProvider.currentDockSnapshot else {
58	            state = .failed("Dock stream state is not loaded.")
59	            selectedRowIDs = []
60	            return
61	        }
62	        let preview = await dataEngine.makePreview(from: dockSnapshot, rule: rule)
63	        if let message = preview.unavailableMessage {
64	            state = .failed(message)
65	            selectedRowIDs = []
66	        } else {
67	            state = .preview(preview)
68	            selectedRowIDs = Set(preview.candidates.map(\.threadIdentity))
69	        }
70	        executionResults = []
71	        executionTotalCount = 0
72	    }
73	
74	    public func setSelected(_ selected: Bool, rowID: HostScopedThreadID) {
75	        if selected {
76	            selectedRowIDs.insert(rowID)
77	        } else {
78	            selectedRowIDs.remove(rowID)
79	        }
80	    }
81	
82	    public func stopRemaining() {
83	        stopRemainingRequested = true
84	    }
85	
86	    @discardableResult
87	    public func archiveSelected() async -> [ArchiveCleanupExecutionResult] {
88	        guard case .preview(let preview) = state else {
89	            return []
90	        }
91	        let rows = preview.candidates.filter { selectedRowIDs.contains($0.threadIdentity) }
92	        return await archiveRows(rows)
93	    }
94	
95	    @discardableResult
96	    public func archiveFailedResults() async -> [ArchiveCleanupExecutionResult] {
97	        guard case .preview(let preview) = state else {
98	            return []
99	        }
100	        let failedRowIDs = Set(
101	            executionResults.compactMap { result -> HostScopedThreadID? in
102	                if case .failed = result.status {
103	                    return result.row.threadIdentity
104	                }
105	                return nil
106	            }
107	        )
108	        let rows = preview.candidates.filter { failedRowIDs.contains($0.threadIdentity) }
109	        return await archiveRows(rows)
110	    }
111	
112	    private func archiveRows(
113	        _ rows: [DockRowViewModel]
114	    ) async -> [ArchiveCleanupExecutionResult] {
115	        guard !rows.isEmpty else {
116	            return []
117	        }
118	
119	        isExecuting = true
120	        stopRemainingRequested = false
121	        executionResults = []
122	        executionTotalCount = rows.count
123	        defer {
124	            isExecuting = false
125	        }
126	
127	        var results: [ArchiveCleanupExecutionResult] = []
128	        for row in rows {
129	            if stopRemainingRequested {
130	                results.append(ArchiveCleanupExecutionResult(row: row, status: .skipped))
131	                executionResults = results
132	                continue
133	            }
134	            guard let host = hostConfiguration(for: row) else {
135	                results.append(ArchiveCleanupExecutionResult(row: row, status: .failed("Host is no longer configured.")))
136	                executionResults = results
137	                continue
138	            }
139	            do {
140	                try await archiver.archiveThread(row.threadID, on: host)
141	                selectedRowIDs.remove(row.threadIdentity)
142	                results.append(ArchiveCleanupExecutionResult(row: row, status: .archived))
143	            } catch {
144	                results.append(ArchiveCleanupExecutionResult(row: row, status: .failed(error.localizedDescription)))
145	            }
146	            executionResults = results
147	        }
148	        executionResults = results
149	        return results
150	    }
151	
152	    private func hostConfiguration(for row: DockRowViewModel) -> DockHostConfiguration? {
153	        if case .preview(let preview) = state,
154	           let resolved = preview.hostIdentityResolver.resolve(
155	               rowHostID: row.hostID,
156	               sourceConfiguredHostID: row.sourceHostID
157	           ) {
158	            return resolved.host
159	        }
160	        if let sourceHostID = row.sourceHostID,
161	           let host = hosts.first(where: { $0.id == sourceHostID }) {
162	            return host
163	        }
164	        return DockHostIdentityResolver(hosts: hosts)
165	            .resolve(rowHostID: row.hostID, sourceConfiguredHostID: row.sourceHostID)?
166	            .host
167	    }
168	}
