1	import Foundation
2	
3	actor LocalMetadataEngine {
4	    private let store: any LocalThreadMetadataStoring
5	    private let now: @Sendable () -> Date
6	    private var values: [LocalThreadMetadataKey: LocalThreadMetadata]
7	
8	    init(
9	        store: any LocalThreadMetadataStoring,
10	        initialValues: [LocalThreadMetadataKey: LocalThreadMetadata] = [:],
11	        now: @escaping @Sendable () -> Date = Date.init
12	    ) {
13	        self.store = store
14	        self.values = initialValues
15	        self.now = now
16	    }
17	
18	    func load() async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
19	        values = try await store.load()
20	        return values
21	    }
22	
23	    func replace(_ values: [LocalThreadMetadataKey: LocalThreadMetadata]) {
24	        self.values = values
25	    }
26	
27	    func migrateHostAliases(
28	        using resolver: DockHostIdentityResolver
29	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
30	        var changed = false
31	        var nextValues: [LocalThreadMetadataKey: LocalThreadMetadata] = [:]
32	        let entries = values.sorted { lhs, rhs in
33	            let lhsKey = [lhs.key.hostID, lhs.key.backendSessionID, lhs.key.threadID].joined(separator: "\u{1f}")
34	            let rhsKey = [rhs.key.hostID, rhs.key.backendSessionID, rhs.key.threadID].joined(separator: "\u{1f}")
35	            return lhsKey < rhsKey
36	        }
37	
38	        for (key, metadata) in entries {
39	            let logicalHostID = resolver.migrationLogicalHostID(forAlias: key.hostID) ?? key.hostID
40	            let nextKey = LocalThreadMetadataKey(
41	                hostID: logicalHostID,
42	                backendSessionID: key.backendSessionID,
43	                threadID: key.threadID
44	            )
45	            changed = changed || nextKey != key
46	            if let existing = nextValues[nextKey] {
47	                nextValues[nextKey] = key == nextKey
48	                    ? Self.mergedMetadata(metadata, existing)
49	                    : Self.mergedMetadata(existing, metadata)
50	                changed = true
51	            } else {
52	                nextValues[nextKey] = metadata
53	            }
54	        }
55	
56	        let normalizedValues = PinnedMetadataOrdering.normalized(nextValues)
57	        guard changed || normalizedValues != values else {
58	            values = normalizedValues
59	            return normalizedValues
60	        }
61	        values = try await store.save(normalizedValues)
62	        return values
63	    }
64	
65	    func setLabel(
66	        _ label: String?,
67	        for key: LocalThreadMetadataKey
68	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
69	        var metadata = values[key] ?? LocalThreadMetadata()
70	        metadata.label = label
71	        return try await save(metadata: metadata, for: key)
72	    }
73	
74	    func setRail(
75	        _ rail: DockRowRail?,
76	        for key: LocalThreadMetadataKey
77	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
78	        var metadata = values[key] ?? LocalThreadMetadata()
79	        metadata.rail = rail
80	        return try await save(metadata: metadata, for: key)
81	    }
82	
83	    func setPinned(
84	        _ isPinned: Bool,
85	        for row: DockRowViewModel
86	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
87	        let key = row.metadataKey
88	        var nextValues = PinnedMetadataOrdering.normalized(values)
89	        var metadata = nextValues[key] ?? LocalThreadMetadata()
90	        if isPinned {
91	            let wasPinned = metadata.isPinned
92	            metadata.isPinned = true
93	            metadata.pinnedAt = metadata.pinnedAt ?? now()
94	            if !wasPinned || metadata.pinnedOrder == nil {
95	                metadata.pinnedOrder = PinnedMetadataOrdering.nextOrder(in: nextValues, excluding: key)
96	            }
97	        } else {
98	            metadata.isPinned = false
99	            metadata.pinnedAt = nil
100	            metadata.pinnedOrder = nil
101	        }
102	        nextValues[key] = metadata
103	        return try await save(metadataValues: PinnedMetadataOrdering.normalized(nextValues))
104	    }
105	
106	    func reorderPinnedRows(
107	        _ visibleRowsInNewOrder: [DockRowViewModel]
108	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
109	        var nextValues = PinnedMetadataOrdering.normalized(values)
110	        let visibleKeys = PinnedMetadataOrdering.uniqueKeys(
111	            visibleRowsInNewOrder.map(\.metadataKey).filter { nextValues[$0]?.isPinned == true }
112	        )
113	        guard visibleKeys.count > 1 else {
114	            return nextValues
115	        }
116	
117	        let visibleKeySet = Set(visibleKeys)
118	        let orderedPinnedKeys = PinnedMetadataOrdering.orderedKeys(in: nextValues)
119	        var reorderedVisibleKeys = visibleKeys.makeIterator()
120	        let mergedKeys = orderedPinnedKeys.compactMap { key in
121	            if visibleKeySet.contains(key) {
122	                return reorderedVisibleKeys.next()
123	            }
124	            return key
125	        }
126	
127	        for (index, key) in mergedKeys.enumerated() {
128	            guard var metadata = nextValues[key], metadata.isPinned else {
129	                continue
130	            }
131	            metadata.pinnedOrder = index
132	            nextValues[key] = metadata
133	        }
134	        return try await save(metadataValues: nextValues)
135	    }
136	
137	    private func save(
138	        metadata: LocalThreadMetadata,
139	        for key: LocalThreadMetadataKey
140	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
141	        values = try await store.save(metadata.isEmpty ? nil : metadata, for: key)
142	        return values
143	    }
144	
145	    private func save(
146	        metadataValues nextValues: [LocalThreadMetadataKey: LocalThreadMetadata]
147	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
148	        let persistedValues = nextValues.filter { !$0.value.isEmpty }
149	        guard values != persistedValues else {
150	            return values
151	        }
152	        values = try await store.save(persistedValues)
153	        return values
154	    }
155	
156	    private static func mergedMetadata(
157	        _ current: LocalThreadMetadata,
158	        _ incoming: LocalThreadMetadata
159	    ) -> LocalThreadMetadata {
160	        var result = current
161	        if result.label == nil {
162	            result.label = incoming.label
163	        }
164	        if result.rail == nil {
165	            result.rail = incoming.rail
166	        }
167	        guard incoming.isPinned else {
168	            return result
169	        }
170	
171	        result.isPinned = true
172	        if let incomingPinnedAt = incoming.pinnedAt {
173	            if let currentPinnedAt = result.pinnedAt {
174	                result.pinnedAt = min(currentPinnedAt, incomingPinnedAt)
175	            } else {
176	                result.pinnedAt = incomingPinnedAt
177	            }
178	        }
179	        if let incomingPinnedOrder = incoming.pinnedOrder {
180	            if let currentPinnedOrder = result.pinnedOrder {
181	                result.pinnedOrder = min(currentPinnedOrder, incomingPinnedOrder)
182	            } else {
183	                result.pinnedOrder = incomingPinnedOrder
184	            }
185	        }
186	        return result
187	    }
188	}
