61	function walk(value, visit) {
62	  if (Array.isArray(value)) {
63	    value.forEach((entry) => walk(entry, visit));
64	    return;
65	  }
66	  if (!value || typeof value !== "object") {
67	    return;
68	  }
69	  for (const [key, child] of Object.entries(value)) {
70	    visit(key, child);
71	    walk(child, visit);
